steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    query {
      issue(identifier: \"WEB-5\") {
        id
        identifier
        title
        comments(first: 50) {
          nodes {
            id
            body
            resolved
            createdAt
            user {
              id
              name
              email
            }
            replies {
              nodes {
                id
                body
                resolved
                user {
                  id
                  name
                  email
                }
              }
            }
          }
        }
      }
    }"
  }'
